\set ON_ERROR_STOP on
-- Native psql control file; never pass to db push / a transactional migration runner.
-- Source SHA256: 8375774382342cd457ae39cece2f1eac8a4ae8e5351c0839f5171242f9d6d75d
set role postgres;
do $release_lock$ begin if not pg_try_advisory_lock(191019,20001516) then raise lock_not_available using message='Another timekeeping covering-index release owns the deployment lock';end if;end $release_lock$;
begin read only;
do $bounds$ begin
 if current_database()<>'postgres' or current_user<>'postgres' or inet_server_port()<>5432 then raise check_violation using message='Online index database/role/port precondition failed';end if;
 if current_setting('lock_timeout')<>'2s' or current_setting('statement_timeout')<>'30s' then raise check_violation using message='Online index startup timeouts must be 2s lock / 30s statement';end if;
 if (select pg_get_userbyid(relowner) from pg_class where oid='public.shifts'::regclass)<>'postgres' then raise check_violation using message='Shift relation owner drift';end if;
 if (select count(*) from pg_roles r cross join lateral unnest(r.rolconfig) c(setting) where r.rolname in ('authenticated','authenticator') and c.setting='statement_timeout=8s')<>2 or exists(select 1 from pg_roles r cross join lateral unnest(r.rolconfig) c(setting) where r.rolname in ('authenticated','authenticator') and c.setting like 'statement_timeout=%' and c.setting<>'statement_timeout=8s') then raise check_violation using message='Authenticated timeout differs from unchanged 8s boundary';end if;
 if not exists(select 1 from pg_class where oid='public.shifts'::regclass and relkind='r' and relrowsecurity and not relforcerowsecurity) then raise check_violation using message='Shift RLS/relation contract differs';end if;
 if (select count(*) from (values ('id','uuid'),('starts_at','timestamp with time zone'),('ends_at','timestamp with time zone'),('schedule_id','uuid'),('canceled_at','timestamp with time zone')) expected(name,type) join pg_attribute a on a.attrelid='public.shifts'::regclass and a.attname=expected.name and a.atttypid=expected.type::regtype and not a.attisdropped)<>5 then raise check_violation using message='Shift covering-index column type contract differs';end if;
 if not exists(select 1 from pg_index i join pg_attribute a on a.attrelid=i.indrelid and a.attname='id' where i.indrelid='public.shifts'::regclass and i.indisprimary and i.indisvalid and i.indnkeyatts=1 and i.indkey[0]=a.attnum) then raise check_violation using message='Shift UUID id primary key contract differs';end if;
end $bounds$;
do $functions$ declare expected jsonb; actual jsonb; begin
 for expected in select value from jsonb_array_elements($expected$[{"acl":"{postgres=X/postgres}","config":["search_path=\"\""],"defaults":"({CONST :consttype 2950 :consttypmod -1 :constcollid 0 :constlen 16 :constbyval false :constisnull true :location -1 :constvalue <>})","identity":"private.get_effective_time_events(uuid)","owner":"postgres","security_definer":true,"source_hash":"e4e6ab15b4a6bdca294cc4d250398396","volatility":"s"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","config":["search_path=\"\""],"defaults":null,"identity":"private.get_timekeeping_review_base(date,date)","owner":"postgres","security_definer":true,"source_hash":"2bf025842841d13fa8a4f9facab445e7","volatility":"v"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","config":["search_path=\"\""],"defaults":null,"identity":"private.get_timekeeping_review_operations_base(date,date)","owner":"postgres","security_definer":true,"source_hash":"54a94325d91b44d34e7c4e9f59aa79ce","volatility":"v"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","config":["search_path=\"\""],"defaults":null,"identity":"private.get_timekeeping_review_pre_payroll_week_allocation(date,date)","owner":"postgres","security_definer":true,"source_hash":"50d56676c0b0daa7d2f795dc85e1b074","volatility":"v"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","config":["search_path=\"\""],"defaults":null,"identity":"private.get_timekeeping_review_preferred_name_boundary_base(date,date)","owner":"postgres","security_definer":true,"source_hash":"8b3d65f5db03d490831f3f5e62786a5e","volatility":"v"},{"identity":"public.get_timekeeping_review(date,date)","source_hash":"9656bc6ff66fdf926a0c09c5f4852d24","owner":"postgres","acl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","config":["search_path=\"\""],"security_definer":true,"volatility":"v","defaults":null}]$expected$::jsonb) loop
 select jsonb_build_object('identity',expected->>'identity','source_hash',md5(pg_get_functiondef(oid)),'owner',pg_get_userbyid(proowner),'acl',proacl::text,'config',proconfig,'security_definer',prosecdef,'volatility',provolatile::text,'defaults',proargdefaults::text) into strict actual from pg_proc where oid=(expected->>'identity')::regprocedure;
 if actual is distinct from expected then raise check_violation using message='Exact installed timekeeping function/source/security precondition failed';end if;
 end loop;
end $functions$;
do $ledger$ begin if exists(select 1 from supabase_migrations.schema_migrations where version='20261020001516') then raise duplicate_object using message='Online index version already ledgered; no unledgered rebuild permitted';end if;end $ledger$;
do $health$ begin
 if (select count(*) from pg_stat_activity where datname=current_database())>=48 then raise check_violation using message='Online index connection headroom gate failed';end if;
 if exists(select 1 from pg_stat_activity where datname=current_database() and pid<>pg_backend_pid() and (cardinality(pg_blocking_pids(pid))>0 or (xact_start is not null and xact_start<clock_timestamp()-interval '30 seconds'))) then raise check_violation using message='Online index blocker/old-transaction gate failed';end if;
 if exists(select 1 from pg_index where indrelid='public.shifts'::regclass and (not indisvalid or not indisready)) then raise check_violation using message='Shift relation already has an invalid/unready index';end if;
end $health$;
do $index_absent$ begin
 if to_regclass('public.shifts_timekeeping_candidate_cover_idx') is not null then raise duplicate_object using message='Named covering index already exists; inspect and use reviewed resume/cleanup mode';end if;
 if exists(select 1 from pg_index i where i.indrelid='public.shifts'::regclass and i.indpred is not null and pg_get_expr(i.indpred,i.indrelid)='(canceled_at IS NULL)' and i.indnkeyatts=1 and i.indnatts=4 and (select array_agg(pg_get_indexdef(i.indexrelid,k,true) order by k) from generate_series(1,4) k)=array['id','starts_at','ends_at','schedule_id']) then raise duplicate_object using message='Equivalent existing covering index found; no duplicate build permitted';end if;
end $index_absent$;
select jsonb_build_object('observedAt',clock_timestamp(),'database',current_database(),'role',current_user,'connections',(select count(*) from pg_stat_activity where datname=current_database()),'relation',jsonb_build_object('rowsEstimate',c.reltuples,'pages',c.relpages,'allVisiblePages',c.relallvisible,'allVisibleFraction',round(c.relallvisible::numeric/nullif(c.relpages,0),4),'bytes',pg_relation_size(c.oid),'lastVacuum',s.last_vacuum,'lastAutovacuum',s.last_autovacuum,'lastAnalyze',s.last_analyze,'lastAutoanalyze',s.last_autoanalyze,'liveTuplesEstimate',s.n_live_tup,'deadTuplesEstimate',s.n_dead_tup,'updates',s.n_tup_upd,'hotUpdates',s.n_tup_hot_upd,'inserts',s.n_tup_ins,'modificationsSinceAnalyze',s.n_mod_since_analyze),'candidateAbsent',to_regclass('public.shifts_timekeeping_candidate_cover_idx') is null,'ledgerRows',(select count(*) from supabase_migrations.schema_migrations),'reviewRoleTimeouts',(select jsonb_agg(jsonb_build_object('role',rolname,'config',rolconfig)) from pg_roles where rolname in ('authenticated','authenticator'))) as preflight from pg_class c join pg_stat_user_tables s on s.relid=c.oid where c.oid='public.shifts'::regclass;
rollback;
select pg_advisory_unlock(191019,20001516);
